from .. import executor
from .base_session import BaseSession, Session


class NewSession(BaseSession):
    def __init__(self, alias, config, timeout=30):
        super(NewSession, self).__init__(alias, config, timeout)

    def __enter__(self):
        timeout = self._calculate_timeout()
        executor = self._create_connected_executor(timeout)
        self._config.install_location = self._config.install_location or self._get_install_location(executor)
        btssm_cmd_builder = self._create_btssm_cmd_builder()
        trs_cmd_builder = self._create_trs_cmd_builder(executor)
        cl_cmd_builder = self._create_cl_cmd_builder(executor)
        temp_dir = self._create_temp_dir(executor)
        btssm = self._create_btssm(executor, temp_dir)
        scfc_validator = self._create_scfc_validator(executor, btssm_cmd_builder, temp_dir)
        scfc_fixer = self._create_scfc_fixer(btssm_cmd_builder)
        self.session = Session(self._config.log_path, btssm_cmd_builder, cl_cmd_builder, trs_cmd_builder,
                               executor, btssm, temp_dir, scfc_validator, scfc_fixer, self._config.trs_ip)
        return self.session

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._remove_temp_dir()
        self._disconnect_executor()

    def _create_connected_executor(self, timeout):
        executor_obj = executor.Executor(self._config.ssh_connection_params, self._config.ssh_login_params,
                                         self._config.log_path, timeout, self._config.get('rc_only', False))
        executor_obj.connect()
        return executor_obj
